import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 내부 단위시스템이 보낸 요청이므로 연계 방향은 항상 수신(RECEIVE)이다.
const DIRECTION = 'RECEIVE';
// 가정: 연계 대상 시스템별 구체 항목·형식은 표준 수립 과정에서 정하므로, 여기서는 길이와 문자열 여부만 검사한다.
const TARGET_SYSTEM_MAX = 50;
const INTERFACE_NAME_MAX = 100;

@Controller('api/v1')
export class FnSir00201Controller {
  @Post('/integrations/internal-systems')
  @HttpCode(200)
  async receiveInternalSystemIntegration(@Req() req: Request) {
    const user = currentUser(req);
    const data = checks.inputOf(req.body);

    const targetSystem = data['targetSystem'];
    const interfaceName = data['interfaceName'];
    const requestSummary = data['requestSummary'];

    if (typeof targetSystem !== 'string' || targetSystem.trim() === '' || targetSystem.length > TARGET_SYSTEM_MAX) {
      throw new ApiError(422, 'INTEGRATION_REQUEST_INVALID', '연계 대상 시스템은 필수이며 50자 이하여야 합니다.');
    }
    if (interfaceName !== undefined && interfaceName !== null) {
      if (typeof interfaceName !== 'string' || interfaceName.length > INTERFACE_NAME_MAX) {
        throw new ApiError(422, 'INTEGRATION_REQUEST_INVALID', '인터페이스 이름은 100자 이하의 문자열이어야 합니다.');
      }
    }
    if (requestSummary !== undefined && requestSummary !== null) {
      if (typeof requestSummary !== 'string') {
        throw new ApiError(422, 'INTEGRATION_REQUEST_INVALID', '연계 요청 데이터는 문자열이어야 합니다.');
      }
    }

    return transaction(async (db) => {
      // 검증을 통과한 요청은 처리 결과 SUCCESS로 이력을 남긴다 (가정).
      const rows = await db.query(
        `INSERT INTO integration_log (
           target_system, direction, interface_name, result_status,
           occurred_at, request_summary, created_at, updated_at
         ) VALUES (
           :targetSystem, :direction, :interfaceName, 'SUCCESS',
           now(), :requestSummary, now(), now()
         )
         RETURNING result_status AS "resultStatus", failure_reason AS "failureReason"`,
        {
          targetSystem: targetSystem.trim(),
          direction: DIRECTION,
          interfaceName: interfaceName ?? null,
          requestSummary: requestSummary ?? null,
        },
      );
      return rows[0];
    });
  }
}

