import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Form, Pager, Tiles, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

const PAGE_SIZE = 10;

export default function FnSir00201Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [targetSystem, setTargetSystem] = useState('');
  const [interfaceName, setInterfaceName] = useState('');
  const [requestSummary, setRequestSummary] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const successCount = results.filter((r) => r['resultStatus'] === 'SUCCESS').length;
  const failureCount = results.filter((r) => r['resultStatus'] === 'FAILURE').length;
  const rows = results.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  const openForm = () => {
    setTargetSystem('');
    setInterfaceName('');
    setRequestSummary('');
    setOpen(true);
  };

  const submit = async () => {
    if (targetSystem.trim() === '') {
      throw new Error('연계 대상 시스템을 입력하세요.');
    }
    const res = await call(
      'POST',
      '/integrations/internal-systems',
      role,
      { targetSystem: targetSystem.trim(), interfaceName, requestSummary },
    );
    const record: Row = {
      targetSystem: targetSystem.trim(),
      interfaceName,
      requestSummary,
      resultStatus: res['resultStatus'],
      failureReason: res['failureReason'],
      requestedAt: new Date().toISOString(),
    };
    setResults([record, ...results]);
    setPage(0);
    setOpen(false);
    notify('연계 요청을 처리했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['전체 요청', <span>{results.length}</span>],
            ['성공', <span>{successCount}</span>],
            ['실패', <span>{failureCount}</span>],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>연계 처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openForm}>연계 요청</button>
        </Band>
        <DataTable
          columns={[
            { key: 'targetSystem', label: '연계 대상 시스템' },
            { key: 'interfaceName', label: '인터페이스 이름' },
            { key: 'resultStatus', label: '연계 결과', render: (r) => <Badge value={r['resultStatus']} /> },
            { key: 'failureReason', label: '실패 사유' },
            { key: 'requestedAt', label: '요청 시각', render: (r) => <DateText value={r['requestedAt']} time /> },
          ]}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty="처리한 연계 요청이 없습니다."
        />
        <Pager page={page} size={PAGE_SIZE} total={results.length} onPage={setPage} />
      </section>
      {open && (
        <Drawer title="연계 요청" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="요청">
            <Field label="연계 대상 시스템" required>
              <TextInput value={targetSystem} onChange={setTargetSystem} placeholder="예: Tcon" />
            </Field>
            <Field label="인터페이스 이름">
              <TextInput value={interfaceName} onChange={setInterfaceName} />
            </Field>
            <Field label="연계 요청 데이터" wide>
              <TextInput value={requestSummary} onChange={setRequestSummary} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="연계 결과 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['연계 대상 시스템', String(detail['targetSystem'] ?? '')],
              ['인터페이스 이름', String(detail['interfaceName'] ?? '')],
              ['연계 요청 데이터', String(detail['requestSummary'] ?? '')],
              ['연계 결과', <Badge value={detail['resultStatus']} />],
              ['실패 사유', String(detail['failureReason'] ?? '')],
              ['요청 시각', <DateText value={detail['requestedAt']} time />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
